const menu=document.querySelector('#menu'),nav=document.querySelector('#navigation');menu?.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'×':'☰'});nav?.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='☰'}));
const reduced=matchMedia('(prefers-reduced-motion: reduce)');const video=document.querySelector('.statement video'),control=document.querySelector('#video-toggle');if(reduced.matches){video?.pause();if(control)control.textContent='▶'}control?.addEventListener('click',()=>{if(video.paused){video.play().catch(()=>{});control.textContent='Ⅱ';control.setAttribute('aria-label','หยุดวิดีโอ')}else{video.pause();control.textContent='▶';control.setAttribute('aria-label','เล่นวิดีโอ')}});
Promise.race([document.fonts.ready,new Promise(resolve=>setTimeout(resolve,1800))]).then(()=>requestAnimationFrame(()=>document.body.classList.add('is-ready')));
if(!reduced.matches){const observer=new IntersectionObserver(entries=>{for(const entry of entries){if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}}},{threshold:.12});document.querySelectorAll('.display,.intro-body p,.feature-list article,.business-grid>a,.news-grid>a').forEach(el=>{if(el.classList.contains('display'))el.innerHTML=el.innerHTML.split(/<br\s*\/?\s*>/i).map((line,i)=>`<span class="heading-mask" style="--delay:${i*95}ms"><span>${line}</span></span>`).join('');else if(el.parentElement.matches('.business-grid,.news-grid'))el.style.setProperty('--delay',`${[...el.parentElement.children].indexOf(el)*110}ms`);el.classList.add('reveal');observer.observe(el)})}
